"""Legacy-compatible numeric division for the modern platform."""

from __future__ import annotations


def _legacy_number(value: object) -> float:
    """Coerce a supported legacy value to a numeric float."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        if value.strip() == "":
            return 0.0

    try:
        return float(value)
    except Exception:
        # Preserve the legacy numeric-context fallback for unusable values.
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using Meridian CRM's division-by-zero semantics."""
    numerator = _legacy_number(a)
    denominator = _legacy_number(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / denominator, []
    except Exception:
        # The public operation must never propagate an operand-related error.
        return 0.0, ["SCRIPT_DIV0"]
